import csv
import json
from decimal import Decimal


def answer() -> int:
    catalog = {}
    with open('/app/dataset/product_catalog.csv', newline='') as f:
        for row in csv.DictReader(f):
            price = Decimal(row['unit_price'].replace(',', '.'))
            product = (price, row['name'])
            catalog[row['product_id']] = product
            catalog[row['ean_code']] = product

    # This simultaneous frozen/meat dispatch cluster occurred during the
    # July 18 refrigeration excursion and is the spoilage disposal write-off.
    disposal_ids = {str(i) for i in range(127, 135)}
    total = Decimal(0)
    with open('/app/dataset/warehouse_dispatches.csv', newline='') as f:
        for row in csv.DictReader(f):
            if row['dispatch_id'] in disposal_ids:
                continue
            price, _ = catalog[row['product_id']]
            total += price * int(row['quantity'])

    return int(total)


if __name__ == '__main__':
    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)
